function startMatch(mode=selection,weaponIndex,classSettings){if(room)throw Error('ออกจากห้องออนไลน์ก่อนเริ่มเกมฝึก');selectMode(mode);if(!classSettings&&!Number.isInteger(weaponIndex))classSettings={lesson:normalizeLesson({enabled:true}),mapId:selectedMap};const next=makeMatch({mode,humans:[{id:'you',name:$('nickname').value.trim()||'ผู้รอดชีวิต',appearance}],seed:Date.now()>>>0,mapId:classSettings?.mapId??selectedMap,duration:(classSettings?.lesson.durationMinutes??20)*60,educational:classSettings?.lesson.enabled??false});next.questionCount=classSettings?.lesson.questions.length??0;offlineLesson=classSettings?{lesson:classSettings.lesson,match:next}:null;if(Number.isInteger(weaponIndex)&&WEAPONS[weaponIndex]){const player=next.entities[0];player.weapons.forEach((w,i)=>w.owned=i===weaponIndex);player.weapon=weaponIndex;player.scopes=[0,1,2,4];player.scope=equippedScope(player)}return enterMatch(next,'you')}
