function membersAlive(team){return match.entities.some(e=>e.team===team&&living(e))}
async function request(operation,data){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const response=await fetch('/api/rooms/'+operation,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:controller.signal});let result;try{result=await response.json()}catch{throw Error('เชื่อมต่อห้องไม่ได้ กรุณาลองอีกครั้ง')}if(!response.ok)throw Object.assign(Error(result.error||'เชื่อมต่อห้องไม่ได้'),{status:response.status});return result}catch(error){if(controller.signal.aborted)throw Error('การเชื่อมต่อช้า กำลังลองใหม่');throw error}finally{clearTimeout(timeout)}}
async function connectRoom(operation,extra={}){if(requestPending)return;if(room)throw Error('อยู่ในห้องแล้ว');requestPending=true;unlockAudio();$('start').disabled=true;$('lobby-error').textContent='กำลังเชื่อมต่อ…';$('join-error').textContent='';try{await features?.ready;if(!features?.token)await features?.refresh();const result=await request(operation,{profileToken:features?.token,name:$('nickname').value,appearance,mode:selection,mapId:selectedMap,...extra,code:$('room-code').value.trim().toUpperCase()});room={...result,token:result.token};sessionStorage.setItem('lastIsland.room',JSON.stringify({code:room.code,token:room.token}));chooseMap(room.mapId);selectMode(room.mode);ui='room';meter.reset();document.body.classList.add('in-room');resetInput();$('join-panel').hidden=true;$('room-panel').hidden=false;renderRoom();sound.play('queue');startPolling();return getState()}catch(error){$('lobby-error').textContent=error.message;$('join-error').textContent=error.message;throw error}finally{requestPending=false;$('start').disabled=false}}
const warmQueue=[],warmed=new Set();let warmTimer=null;function scheduleWarm(){for(let t=0;t<10;t++)for(let slot=0;slot<5;slot++){const a=botAppearance(t,slot),key=appearanceKey(a);if(!warmed.has(key)){warmed.add(key);warmQueue.push(a)}}for(const p of room?.players??[]){const key=appearanceKey(p.appearance);if(!warmed.has(key)){warmed.add(key);warmQueue.unshift(p.appearance)}}if(warmTimer||!warmQueue.length)return;const work=()=>{warmTimer=null;if(ui==='playing'||ui==='ended')return;const a=warmQueue.shift();if(a)warmAvatar(a);if(warmQueue.length)warmTimer=setTimeout(work,40)};warmTimer=setTimeout(work,40)}
function renderRoom(){if(room){scheduleWarm();waitingRoom?.render(room);$('room-map-name').textContent=mapInfo(room.mapId).name;$('room-lesson-time').textContent=room.lesson.durationMinutes+' นาที'+(room.lesson.enabled?' · ตอบคำถามรับของ':'');classroom?.update(room,null,null)}}
async function refreshTeacherRoom(){if(!room)return;const code=room.code,token=room.token,next=await request('poll',{code,token,controls:controls(),knownLoot:lootStamp(room.match)});if(!room||room.code!==code||room.token!==token)return;room=mergeRoomSnapshot(room,next);if(ui==='room')renderRoom();features?.update(room,match,self());classroom?.update(room,match,self())}
function startPolling(){clearTimeout(pollTimer);const epoch=++pollEpoch;const poll=async()=>{if(!room)return;const started=performance.now();try{let next=await request('poll',{code:room.code,token:room.token,controls:controls(),knownLoot:lootStamp(room.match)});ping=Math.round(performance.now()-started);lastServer=performance.now();if(!room||epoch!==pollEpoch)return;room=mergeRoomSnapshot(room,next);next=room;if(next.match){if(next.match.state==='playing'&&(!match||match.id!==next.match.id||ui==='room')){enterMatch(next.match,room.id)}else if(match&&ui!=='room'){match=next.match;prediction.receive(self(),controls(),Math.min(.75,ping/2000),colliders(match),match.drop);actions=actions.filter(a=>a.seq>(self()?.lastAction??0))}}features?.update(room,match,self());classroom?.update(room,match,self());if(room.match?.state==='playing'&&self()?.status==='alive'&&room.learning?.question?.broadcastId&&classroom?.receiveBroadcast(room.learning.question,room.match?.id))features?.close();if(room.pausedAt){resetInput();prediction.reset(self(),match.drop);}if(ui==='room')renderRoom();$('connection').textContent='ออนไลน์ · '+ping+' ms';}catch(error){$('connection').textContent=error.status===401?'เซสชันหมดอายุ · กลับเข้าห้องใหม่':'กำลังเชื่อมต่อใหม่…';if(ui==='room')$('room-status').textContent=error.message;}finally{if(room&&epoch===pollEpoch)pollTimer=setTimeout(poll,ui==='room'?1000:Math.max(16,150-(performance.now()-started)))}};poll()}
async function restoreRoom(){let saved;try{saved=JSON.parse(sessionStorage.getItem('lastIsland.room'))}catch{}if(!saved?.code||!saved?.token)return;try{const result=await request('join',saved);room={...result,token:saved.token};appearance=normalizeAppearance(room.players.find(p=>p.id===room.id)?.appearance);previewAppearance(appearance);$('equipped-character').textContent=characterInfo(appearance).name;renderParty();chooseMap(room.mapId);selectMode(room.mode);ui='room';meter.reset();document.body.classList.add('in-room');$('room-panel').hidden=false;renderRoom();startPolling()}catch{sessionStorage.removeItem('lastIsland.room')}}
async function launchRoom(){if(!room?.isHost)return;try{const next=await request('start',{code:room.code,token:room.token});room=mergeRoomSnapshot(room,next);enterMatch(next.match,room.id)}catch(e){$('room-status').textContent=e.message;throw e}}
